  insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
  values (v_ver, 41, $academy_deck$choix$academy_deck$, $academy_deck$Examen renforcé$academy_deck$, 2, $academy_deck${"enonce":"Sur le schéma, cas fictif : un client remet toutes ses pièces sauf son justificatif de domicile, périmé depuis trois mois, qu’il promet d’envoyer jeudi. À quel niveau se traite ce dossier ?","choix":["Au premier : pièce manquante ou écart explicable, réglé avec le client","Au deuxième : une pièce manquante ouvre toujours un examen renforcé","Au troisième : une pièce périmée vaut soupçon et se remonte par écrit","À aucun : l’opération peut se faire, la pièce la régularisera jeudi"],"figure":{"ref":"trois_niveaux"}}$academy_deck$::jsonb)
